from pathlib import Path
root=Path(__file__).resolve().parent.parent
assets=root/'web/assets'
css=(assets/'style.css').read_text()
common=(assets/'common.js').read_text()
logo=(assets/'logo.txt').read_text()
head='<!doctype html><html lang="ar" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><meta name="theme-color" content="#211710"><title>{title}</title>{manifest}<style>'+css+'</style></head><body>'
end='<div id="modal" class="modal" role="dialog" aria-modal="true" aria-labelledby="modalTitle"><div class="sheet"><div class="sheet-head"><h2 id="modalTitle"></h2><button aria-label="إغلاق" onclick="closeModal()">×</button></div><div id="modalBody" class="sheet-body"></div></div></div><div id="toast" class="toast" role="status"></div>'
top='<header class="top"><div class="brand"><img src="'+logo+'" alt="طراز"><div><b id="brandName">طِراز</b><small>TIRAZ.SELECT</small></div></div>{buttons}</header>'
store='''<div class="app">'''+top.replace('{buttons}','<button aria-label="السلة" onclick="openCart()">السلة <span id="cartCount" class="badge">0</span></button>')+'''<main><section class="view active" id="homeView"><div class="hero"><small>ساعات ونظارات مختارة بعناية</small><h1>تفاصيل تصنع طِرازك</h1><p>قطع تعبّر عن ذوقك، بتفاصيل كلاسيكية ولمسة عصرية.</p><button class="primary" onclick="filterCategory('all')">تسوّق التشكيلة</button></div><div id="banners"></div><h2>تسوّق حسب التصنيف</h2><div class="cats"><button onclick="filterCategory('mens-watches')">ساعات رجالية</button><button onclick="filterCategory('womens-watches')">ساعات نسائية</button><button onclick="filterCategory('mens-eyewear')">نظارات رجالية</button><button onclick="filterCategory('womens-eyewear')">نظارات نسائية</button></div><div class="row"><h2>وصل حديثاً</h2><button onclick="filterCategory('all')">عرض الكل</button></div><div id="homeProducts" class="products"></div></section><section class="view" id="searchView"><h2>التشكيلة</h2><div class="toolbar"><input id="searchInput" aria-label="البحث" placeholder="اسم المنتج أو الماركة…" oninput="renderCatalog()"><select id="sortProducts" aria-label="الترتيب" onchange="renderCatalog()"><option value="new">الأحدث</option><option value="low">السعر الأقل</option><option value="high">السعر الأعلى</option></select></div><div class="chips">'''+''.join(f'<button class="chip {"selected" if k=="all" else ""}" data-filter="{k}" onclick="filterCategory(\'{k}\')">{n}</button>' for k,n in [('all','الكل'),('men','رجالي'),('women','نسائي'),('classic','كلاسيكي'),('vintage','قديم'),('modern','عصري')])+'''</div><label class="gap"><input id="onlyStock" type="checkbox" style="width:auto" onchange="renderCatalog()">المتوفر فقط</label><div id="searchProducts" class="products"></div></section><section class="view" id="favoritesView"><h2>مفضلتك</h2><div id="favoriteProducts" class="products"></div></section><section class="view" id="profileView"><div id="profileContent"></div></section></main><nav class="bottom" aria-label="التنقل الرئيسي">'''+''.join(f'<button data-view="{k}" class="{"active" if k=="home" else ""}" onclick="nav(\'{k}\')">{n}</button>' for k,n in [('home','الرئيسية'),('search','التشكيلة'),('favorites','المفضلة'),('profile','حسابي')])+'''</nav></div>'''
admin='''<div class="app"><div id="loginScreen" class="login"><div class="login-brand"><img src="'''+logo+'''" alt="طراز"><h1>إدارة طراز</h1><p class="small">الدخول لحسابات الإدارة المفعّلة.</p></div><label>البريد الإلكتروني</label><input id="email" type="email" autocomplete="username"><label>كلمة المرور</label><input id="password" type="password" autocomplete="current-password" onkeydown="if(event.key==='Enter')loginAdmin(document.getElementById('loginButton'))"><button id="loginButton" class="primary" style="width:100%;margin-top:18px" onclick="loginAdmin(this)">تسجيل الدخول</button><button class="secondary" style="margin-top:12px" onclick="adminReset(this)">نسيت كلمة المرور</button></div><div id="mainApp" class="hidden">'''+top.replace('{buttons}','<div class="gap"><small id="roleLabel"></small><button onclick="enablePush()">الإشعارات</button><button onclick="adminPasswordForm()">كلمة المرور</button><button onclick="logoutAdmin(this)">خروج</button></div>')+'''<nav class="tabs">'''+''.join(f'<button data-view="{k}" {"data-permission="+chr(34)+perm+chr(34) if perm else ""} onclick="adminNav(\'{k}\')" class="{"active" if k=="dashboard" else ""}">{n}</button>' for k,n,perm in [('dashboard','الرئيسية',''),('products','المنتجات','content'),('inventory','المخزون','content'),('orders','الطلبات','orders'),('boxes','العلب','content'),('reviews','التقييمات','content'),('banners','البنرات','content'),('settings','الإعدادات','settings'),('integrations','الربط','owner'),('team','المشرفون','owner'),('audit','سجل العمليات','audit')])+'''</nav><main><section class="view active" id="dashboardView"><div class="row"><h2>نظرة على المتجر</h2><button onclick="busy(this,refreshAdmin)">تحديث</button></div><div id="dashboardStats" class="stats"></div><h3 style="margin-top:20px">آخر الطلبات</h3><div id="recentOrders"></div></section><section class="view" id="productsView"><div class="row"><h2>المنتجات والمسودات</h2><button class="primary" onclick="editProduct()">منتج جديد</button></div><div class="toolbar"><input id="productSearch" placeholder="بحث بالاسم أو الماركة" oninput="renderAdminProducts()"><select id="productFilter" onchange="renderAdminProducts()"><option value="all">الكل</option><option value="published">المنشورة</option><option value="draft">المسودات والمخفية</option></select></div><div id="productsList"></div></section><section class="view" id="inventoryView"><h2>المخزون</h2><input id="stockSearch" placeholder="بحث بالمنتج أو اللون أو الرمز" oninput="renderInventory()"><div id="inventoryList"></div></section><section class="view" id="ordersView"><div class="row"><h2>الطلبات</h2><button onclick="busy(this,loadOrders)">تحديث</button></div><div class="toolbar"><input id="orderSearch" placeholder="رقم الطلب أو الاسم أو الهاتف" oninput="renderOrders()"><select id="orderFilter" onchange="renderOrders()"><option value="">كل الحالات</option>'''+''.join(f'<option value="{k}">{n}</option>' for k,n in [('new','جديد'),('confirmed','مؤكد'),('preparing','تجهيز'),('shipped','مشحون'),('delivered','مسلّم'),('cancelled','ملغي'),('rejected','مرفوض')])+'''</select></div><div id="ordersList"></div></section><section class="view" id="boxesView"><div class="row"><h2>العلب</h2><button class="primary" onclick="boxForm()">علبة جديدة</button></div><div id="boxesList"></div></section><section class="view" id="reviewsView"><h2>التقييمات</h2><div id="reviewsList"></div></section><section class="view" id="bannersView"><div class="row"><h2>بنرات المتجر</h2><button class="primary" onclick="bannerForm()">بنر جديد</button></div><div id="bannersList"></div></section><section class="view" id="settingsView"><h2>إعدادات المتجر</h2><div class="panel" id="settingsForm"></div><div class="panel"><h3>إرسال إشعار للزبائن</h3><label>العنوان</label><input id="notifyTitle" maxlength="100"><label>الرسالة</label><textarea id="notifyMessage" maxlength="1000"></textarea><label>رابط داخل المتجر — اختياري</label><input id="notifyUrl"><button class="primary" style="margin-top:15px" onclick="broadcast(this)">إرسال</button></div></section><section class="view" id="integrationsView"><h2>ربط التخزين والإشعارات</h2><p id="integrationState"></p><div class="panel"><label>توكن البوت — عند التغيير فقط</label><input id="botToken" type="password" autocomplete="off"><label>مفتاح الإشعارات — عند التغيير فقط</label><input id="oneSignalKey" type="password" autocomplete="off"><div id="channels"></div><div class="row" style="margin-top:15px"><button class="primary" onclick="saveIntegrations(this)">حفظ الربط</button><button onclick="testTelegram(this)">فحص صلاحية النشر</button></div></div><h3>الإرسال المعلّق</h3><div id="outboxList"></div></section><section class="view" id="teamView"><h2>المشرفون</h2><div class="panel"><label>بريد المشرف الجديد</label><input id="inviteEmail" type="email"><label>الدور</label><select id="inviteRole"><option value="content">المحتوى والمخزون</option><option value="orders">الطلبات فقط</option><option value="admin">إدارة عامة</option></select><button class="primary" style="margin-top:15px" onclick="inviteTeam(this)">إرسال دعوة</button></div><div id="teamList"></div></section><section class="view" id="auditView"><h2>سجل العمليات</h2><div id="auditList"></div></section></main></div></div>'''
for name,title,body,js,manifest in [('index.html','طراز | ساعات ونظارات',store,'store.js','<link rel="manifest" href="./manifest.webmanifest">'),('admin/index.html','إدارة طراز',admin,'admin.js','')]:
    start=head.replace('{title}',title).replace('{manifest}',manifest)
    code=common+'\n'+(assets/js).read_text()
    extra="if('serviceWorker' in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>{});" if name=='index.html' else ''
    (root/'web'/name).write_text(start+body+end+'<script>'+code+'\n'+extra+'</script></body></html>')
